fast_pseudocode:
@triton.autotune(configs=[Config({'XBLOCK': 256}, num_warps=4), ...], key=['xnumel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    ...

# CORRECT: grid must be a lambda reading meta['XBLOCK']
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](args..., xnumel)  # XBLOCK injected by autotune
